package com.calfteam.petcare.utils

object Constants {
    // Endpoint
    const val APPWRITE_ENDPOINT = "https://sgp.cloud.appwrite.io/v1"

    const val PROJECT_ID = "6a23d985002a2a939ce0"

    // ID Database dan Collection
    const val DATABASE_ID = "6a23da110017427c5266"
    const val COLLECTION_PETS_ID = "pets"

    // ID Bucket Storage
    const val BUCKET_PET_IMAGES_ID = "6a247a4500163366f70a"

    // Generate image URL dari Appwrite Storage
    fun getImageUrl(fileId: String): String {
        return "$APPWRITE_ENDPOINT/storage/buckets/$BUCKET_PET_IMAGES_ID/files/$fileId/preview?project=$PROJECT_ID&width=500&height=500"
    }
}

package com.calfteam.petcare.data.repository

import android.content.Context
import android.net.Uri
import android.util.Log
import com.calfteam.petcare.data.model.Pet
import com.calfteam.petcare.utils.Constants
import io.appwrite.Client
import io.appwrite.ID
import io.appwrite.models.InputFile
import io.appwrite.services.Databases
import io.appwrite.services.Storage
import java.io.File

class PetRepository(client: Client) {

    private val storage = Storage(client)
    private val databases = Databases(client)

    // 1. Upload Gambar ke Bucket
    suspend fun uploadPetImage(file: File): Result<String> {
        return try {
            val response = storage.createFile(
                bucketId = Constants.BUCKET_PET_IMAGES_ID,
                fileId = ID.unique(),
                file = InputFile.fromFile(file)
            )
            Result.success(response.id) // Mengembalikan ID file gambar
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    // 2. Simpan Data Pet ke Collection Database
    suspend fun savePetPost(
        name: String,
        breed: String,
        age: String,
        desc: String,
        type: String,
        fileId: String,
        tags: List<String> = emptyList(),
        contact: String = "",
        location: String = "Nearby"
    ): Result<Unit> {
        return try {
            val dataMap = mapOf(
                "petName" to name,          // REQUIRED
                "type" to type,             // REQUIRED - "Adoption" or "Missing"
                "age" to age,
                "description" to desc,      // REQUIRED
                "status" to type,
                "imageId" to fileId,        // REQUIRED - bukan imageUrl!
                "contact" to contact,       // REQUIRED
                "location" to location      // REQUIRED
            )

            // Debug logging
            Log.d("PetRepository", "=== Sending to Appwrite ===")
            Log.d("PetRepository", "DB: ${Constants.DATABASE_ID}")
            Log.d("PetRepository", "Collection: ${Constants.COLLECTION_PETS_ID}")
            dataMap.forEach { (key, value) ->
                Log.d("PetRepository", "  ✓ $key: $value")
            }

            databases.createDocument(
                databaseId = Constants.DATABASE_ID,
                collectionId = Constants.COLLECTION_PETS_ID,
                documentId = ID.unique(),
                data = dataMap
            )
            Log.d("PetRepository", "✅ Success!")
            Result.success(Unit)
        } catch (e: Exception) {
            Log.e("PetRepository", "❌ Error: ${e.message}")
            Result.failure(e)
        }
    }

    // Helper untuk konversi Uri ke File
    fun uriToFile(context: Context, uri: Uri): File {
        val contentResolver = context.contentResolver
        val tempFile = File.createTempFile("pet_image", ".jpg", context.cacheDir)
        val inputStream = contentResolver.openInputStream(uri)
        val outputStream = tempFile.outputStream()
        inputStream?.use { input ->
            outputStream.use { output ->
                input.copyTo(output)
            }
        }
        return tempFile
    }
}

package com.calfteam.petcare.data.repository

import android.content.Context
import android.net.Uri
import android.util.Log
import com.calfteam.petcare.data.model.Pet
import com.calfteam.petcare.utils.Constants
import io.appwrite.Client
import io.appwrite.ID
import io.appwrite.models.InputFile
import io.appwrite.services.Databases
import io.appwrite.services.Storage
import java.io.File

class PetRepository(client: Client) {

    private val storage = Storage(client)
    private val databases = Databases(client)

    // 1. Upload Gambar ke Bucket
    suspend fun uploadPetImage(file: File): Result<String> {
        return try {
            val response = storage.createFile(
                bucketId = Constants.BUCKET_PET_IMAGES_ID,
                fileId = ID.unique(),
                file = InputFile.fromFile(file)
            )
            Result.success(response.id) // Mengembalikan ID file gambar
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    // 2. Simpan Data Pet ke Collection Database
    suspend fun savePetPost(
        name: String,
        breed: String,
        age: String,
        desc: String,
        type: String,
        fileId: String,
        tags: List<String> = emptyList(),
        contact: String = "",
        location: String = "Nearby"
    ): Result<Unit> {
        return try {
            val dataMap = mapOf(
                "petName" to name,          // REQUIRED
                "type" to type,             // REQUIRED - "Adoption" or "Missing"
                "age" to age,
                "description" to desc,      // REQUIRED
                "status" to type,
                "imageId" to fileId,        // REQUIRED - bukan imageUrl!
                "contact" to contact,       // REQUIRED
                "location" to location      // REQUIRED
            )

            // Debug logging
            Log.d("PetRepository", "=== Sending to Appwrite ===")
            Log.d("PetRepository", "DB: ${Constants.DATABASE_ID}")
            Log.d("PetRepository", "Collection: ${Constants.COLLECTION_PETS_ID}")
            dataMap.forEach { (key, value) ->
                Log.d("PetRepository", "  ✓ $key: $value")
            }

            databases.createDocument(
                databaseId = Constants.DATABASE_ID,
                collectionId = Constants.COLLECTION_PETS_ID,
                documentId = ID.unique(),
                data = dataMap
            )
            Log.d("PetRepository", "✅ Success!")
            Result.success(Unit)
        } catch (e: Exception) {
            Log.e("PetRepository", "❌ Error: ${e.message}")
            Result.failure(e)
        }
    }

    // Helper untuk konversi Uri ke File
    fun uriToFile(context: Context, uri: Uri): File {
        val contentResolver = context.contentResolver
        val tempFile = File.createTempFile("pet_image", ".jpg", context.cacheDir)
        val inputStream = contentResolver.openInputStream(uri)
        val outputStream = tempFile.outputStream()
        inputStream?.use { input ->
            outputStream.use { output ->
                input.copyTo(output)
            }
        }
        return tempFile
    }

    // 3. Fetch semua Pet dari Collection Database
    suspend fun getAllPets(): Result<List<Pet>> {
        return try {
            val documents = databases.listDocuments(
                databaseId = Constants.DATABASE_ID,
                collectionId = Constants.COLLECTION_PETS_ID
            )

            val pets = documents.documents.map { doc ->
                Pet(
                    id = doc.id,
                    name = doc.data["petName"]?.toString() ?: "Unknown",
                    breed = doc.data["type"]?.toString()?.takeIf { it.isNotEmpty() } ?: "Unknown Pet",
                    age = doc.data["age"]?.toString() ?: "Unknown",
                    status = doc.data["status"]?.toString()?.takeIf { it in listOf("Available", "Missing") } ?: "Available",
                    distance = doc.data["location"]?.toString() ?: "Nearby",
                    imageUrl = doc.data["imageId"]?.toString() ?: "",
                    tags = emptyList(), // Tags bisa ditambah nanti
                    lastSeen = doc.data["description"]?.toString()
                )
            }

            Log.d("PetRepository", "✅ Fetched ${pets.size} pets from database")
            Result.success(pets)
        } catch (e: Exception) {
            Log.e("PetRepository", "❌ Error fetching pets: ${e.message}")
            Result.failure(e)
        }
    }
}

